define(['jquery', 'mage/url', ], function($, url) {
    "use strict";
    var totalSeconds = 0;

    function startTimerSession() {
        var timer = localStorage.getItem('store_timer');
        var storeName = localStorage.getItem('store_name');
        var msg;
        if (storeName != null) {
            msg = 'Session time: ';
        } else {
            msg = 'Store is loggedin from ';
        }
        if (timer != null) {
            totalSeconds = timer;
        } else {
            totalSeconds = 0
        }
        ++totalSeconds;
        localStorage.setItem('store_timer', totalSeconds);
        var hour = Math.floor(totalSeconds / 3600);
        var minute = Math.floor((totalSeconds - hour * 3600) / 60);
        var seconds = totalSeconds - (hour * 3600 + minute * 60);
        if (hour < 10)
            hour = "0" + hour;
        if (minute < 10)
            minute = "0" + minute;
        if (seconds < 10)
            seconds = "0" + seconds;
        document.getElementById("store_loggedin_msg").innerHTML = msg + hour + ":" + minute + ":" + seconds;
        setTimeout(startTimerSession, 1000);
    }

    function clearStoreSession() {
        localStorage.removeItem('store_timer');
        localStorage.removeItem('store_name');
        var msgEl = document.getElementById("store_loggedin_msg");
        if (msgEl) {
            msgEl.innerHTML = '';
        }
    }
    $.widget('eighteentech.storeheaderlink', {
        options: {
            storeHeaderLink: '#storeheader-link'
        },
        _create: function() {
            var self = this;
            self.getStorelink();
            self.logoutStore();
        },
        logoutStore: function() {
            $(document).on('click', '.store-logout', function() {
                setTimeout(() => {
                    localStorage.removeItem('store_timer');
                    localStorage.removeItem('store_name');
                    document.getElementById("store_loggedin_msg").innerHTML = '';
                }, 1000);
            })
        },
        getStorelink: function() {
            var store_url = BASE_URL + 'salesorder/order/split/order_id/';
            var store_media_url = BASE_URL + 'media/';
            $.ajax({
                url: BASE_URL + 'loginasstore/store/index',
                type: 'GET',
                success: function(response) {
                    if (response.is_logged_in) {
                        if ($('#storeheader-link').length) {
                            if (response.storeId !== 0) {
                                $('#storeheader-link').show();
                                $('.beforestorelogin').hide();
                                $('#storeheader-link').html('<li class="ui-menu-item level0  store menu-item-has-children parent store afterstorelogin"><a class="level-top" title="Store Order List" href="' + store_url + response.storeId + '"><img class="store-img" src="' + store_media_url + 'wysiwyg/store-pic-active.png" alt="Store Order List"><span class="store_code">' + response.storeCode + '</span></a></li>');
                                startTimerSession();
                                localStorage.setItem('store_name', response.storeCode)
                            } else {
                                $('#storeheader-link').hide();
                                $('.beforestorelogin').show();
                                clearStoreSession();
                            }
                        }
                    } else {
                        $('#storeheader-link').hide();
                        $('.beforestorelogin').show()
                        clearStoreSession();
                    }
                },
                error: function(response) {
                    $('#storeheader-link').hide();
                    $('.beforestorelogin').show()
                    clearStoreSession();
                }
            });
        }
    });
    return $.eighteentech.storeheaderlink;
});